import{_ as a,o as s,c as d,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"案例 01 · 饮料品牌短 TVC","description":"","frontmatter":{},"headers":[],"relativePath":"cases/case-01-beverage-tvc.md","filePath":"cases/case-01-beverage-tvc.md","lastUpdated":1786327499000}'),e={name:"cases/case-01-beverage-tvc.md"};function r(p,t,o,l,i,h){return s(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="案例-01-·-饮料品牌短-tvc" tabindex="-1">案例 01 · 饮料品牌短 TVC <a class="header-anchor" href="#案例-01-·-饮料品牌短-tvc" aria-label="Permalink to &quot;案例 01 · 饮料品牌短 TVC&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">这是教学演示案例</p><p>本案例用于展示 <a href="/cases/template">拆解格式</a> 怎么用、一条视频链路的各环节如何衔接。<strong>它不是真实客户项目的复盘</strong>，其中的数字是基于典型情况的合理估计，不是实测数据。</p><p>请把它当作&quot;流程示范&quot;来读，而不是&quot;效果证明&quot;。</p></div><blockquote><p><strong>一句话</strong>：视频链路的核心不是 Prompt 写得多好，而是<strong>走图生视频而不是文生视频</strong>。</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>无糖气泡水</td></tr><tr><td>交付形态</td><td>15 秒竖屏</td></tr><tr><td>投放渠道</td><td>抖音信息流</td></tr><tr><td>工期</td><td>3 天</td></tr><tr><td>出片率</td><td>约 40 条生成 / 6 条采用</td></tr></tbody></table><hr><h2 id="_1-创意点" tabindex="-1">① 创意点 <a class="header-anchor" href="#_1-创意点" aria-label="Permalink to &quot;① 创意点&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>一款无糖气泡水，目标人群是一线城市 22–30 岁的上班族。竞品都在讲&quot;0 糖 0 卡 0 脂&quot;，赛道已经很挤。渠道是抖音信息流，竖屏，前 3 秒决定生死。</p><p>限制：不能宣称任何减肥或健康功效（<a href="/prompts/copywriting">广告合规</a> 的硬约束）。</p><h3 id="洞察" tabindex="-1">洞察 <a class="header-anchor" href="#洞察" aria-label="Permalink to &quot;洞察&quot;">​</a></h3><p>按 <a href="/method/big-idea">Big Idea</a> 里的方法，让 AI 发散 20 条&quot;这群人在下午三点的真实心理&quot;，禁止提产品。从中挑出这一条：</p><blockquote><p>下午三点想喝点带劲的，但奶茶喝完会有负罪感——不是怕胖，是讨厌那种&quot;我又管不住自己&quot;的感觉。</p></blockquote><p>关键在最后半句。<strong>扎人的不是热量，是失控感。</strong></p><h3 id="big-idea" tabindex="-1">Big Idea <a class="header-anchor" href="#big-idea" aria-label="Permalink to &quot;Big Idea&quot;">​</a></h3><blockquote><p><strong>不用忍。</strong></p></blockquote><h3 id="淘汰掉的方向与理由" tabindex="-1">淘汰掉的方向与理由 <a class="header-anchor" href="#淘汰掉的方向与理由" aria-label="Permalink to &quot;淘汰掉的方向与理由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>淘汰理由</th></tr></thead><tbody><tr><td>&quot;0 糖 0 卡，放心喝&quot;</td><td>换成任何竞品都成立 → 不是这个品牌的洞察</td></tr><tr><td>&quot;热爱生活的年轻人&quot;</td><td>正确的废话，看不见画面</td></tr><tr><td>&quot;打工人的续命水&quot;</td><td>梗太熟，一看就是模板，且和产品属性没关系</td></tr></tbody></table><p>「不用忍」能过 <a href="/method/big-idea#一个可操作的判断清单">四条检验</a>：换竞品不成立（竞品在强调&quot;忍得住&quot;的自律叙事）、一句话说得完、能画出多个画面、内含一个&quot;但是&quot;。</p><hr><h2 id="_2-生成链路" tabindex="-1">② 生成链路 <a class="header-anchor" href="#_2-生成链路" aria-label="Permalink to &quot;② 生成链路&quot;">​</a></h2><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① Big Idea 定稿（人）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>② AI 生成两版分镜表，对比取一版（大模型）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>③ 逐镜头生成首帧静图（图像模型）—— 关键步骤</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>④ 首帧 + 动作描述 → 图生视频（视频模型）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑤ 口播稿 → TTS 配音</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑥ 剪辑 + 统一调色 + 字幕（传统软件）</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">第 ③ 步是整条链路的胜负手</p><p>先用图像模型把每个镜头的首帧调到满意，再让它动起来。</p><p>对比直接文生视频：文生视频每次生成，构图、光线、色调都在变，你无法控制。图生视频里画面已经定死，模型只负责让它动——<strong>可控性差一个量级</strong>。</p><p>代价是多一道工序。值得。</p></div><h3 id="分镜表" tabindex="-1">分镜表 <a class="header-anchor" href="#分镜表" aria-label="Permalink to &quot;分镜表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>时长</th><th>景别</th><th>机位</th><th>主体与动作</th><th>光</th><th>运镜</th></tr></thead><tbody><tr><td>1</td><td>0–3s</td><td>特写</td><td>平视</td><td>电脑屏幕右下角时间跳到 15:00，画面其余部分虚化</td><td>屏幕自发光</td><td>固定</td></tr><tr><td>2</td><td>3–5s</td><td>近景</td><td>微俯</td><td>手停在奶茶外卖 App 的下单按钮上，没按</td><td>冷调办公室顶光</td><td>缓慢推近</td></tr><tr><td>3</td><td>5–7s</td><td>中景</td><td>平视</td><td>人转头看向桌上的另一样东西</td><td>侧面窗光</td><td>固定</td></tr><tr><td>4</td><td>7–10s</td><td>特写</td><td>平视</td><td>产品罐身，水珠缓慢滑落</td><td>侧逆光，罐身有亮边</td><td>缓慢环绕</td></tr><tr><td>5</td><td>10–13s</td><td>特写</td><td>微仰</td><td>气泡在液体里缓慢上升</td><td>逆光，液体透亮</td><td>固定，升格</td></tr><tr><td>6</td><td>13–15s</td><td>中景</td><td>平视</td><td>人靠回椅背，表情松弛</td><td>窗光</td><td>缓慢拉远</td></tr></tbody></table><p>结构符合 <a href="/method/storyboard#分镜的三条结构原则">分镜三原则</a>：第 1 镜有异常（时间数字的特写而非人）、相邻景别都在变、产品在第 7 秒出现（总时长的 47%）。</p><h3 id="数字" tabindex="-1">数字 <a class="header-anchor" href="#数字" aria-label="Permalink to &quot;数字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>总生成 / 采用</td><td>约 40 条 / 6 条</td></tr><tr><td>首帧静图</td><td>约 半天</td></tr><tr><td>视频生成</td><td>约 1 天（含大量等待）</td></tr><tr><td>剪辑合成</td><td>约 半天</td></tr><tr><td>返工点</td><td><strong>镜头 5（气泡上升）返工最多</strong>，约占总生成量的三分之一</td></tr></tbody></table><p><strong>关于镜头 5</strong>：液体和气泡是视频模型的高难度项——物理直觉容易崩，气泡会凭空出现或消失、运动方向违反重力。这类镜头排期时要留双倍时间。</p><hr><h2 id="_3-关键-prompt" tabindex="-1">③ 关键 Prompt <a class="header-anchor" href="#_3-关键-prompt" aria-label="Permalink to &quot;③ 关键 Prompt&quot;">​</a></h2><h3 id="prompt-1-·-全片风格包-解决跨镜头调性统一" tabindex="-1">Prompt 1 · 全片风格包（解决跨镜头调性统一） <a class="header-anchor" href="#prompt-1-·-全片风格包-解决跨镜头调性统一" aria-label="Permalink to &quot;Prompt 1 · 全片风格包（解决跨镜头调性统一）&quot;">​</a></h3><p><strong>适用场景</strong> 项目开始时定一次，之后每个镜头原样粘贴，一个字不改。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>饮料广告片风格，冷调偏蓝的办公室环境，产品出现时转为暖色轮廓光，</span></span>
<span class="line"><span>轻微胶片颗粒，电影感，</span></span>
<span class="line"><span>35mm 镜头，浅景深，</span></span>
<span class="line"><span>竖版 9:16，高细节，无文字</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>作用</th></tr></thead><tbody><tr><td>冷调→暖色的转变</td><td>把情绪变化编码进色彩：压抑（冷）→ 释放（暖）。这一句让色彩承担了叙事功能</td></tr><tr><td>轻微胶片颗粒</td><td>去&quot;AI 味&quot;最有效的单个词</td></tr><tr><td>无文字</td><td>生成的中文必然是乱码，字幕后期加</td></tr></tbody></table><p><strong>常见翻车点</strong> 风格包在镜头之间被改了词——哪怕换个同义词，调性都会飘。复制粘贴，不要手打。</p><hr><h3 id="prompt-2-·-镜头-4-首帧-解决产品质感" tabindex="-1">Prompt 2 · 镜头 4 首帧（解决产品质感） <a class="header-anchor" href="#prompt-2-·-镜头-4-首帧-解决产品质感" aria-label="Permalink to &quot;Prompt 2 · 镜头 4 首帧（解决产品质感）&quot;">​</a></h3><p><strong>适用场景</strong> 产品特写的静帧，之后作为图生视频的输入。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一罐带水珠的铝制饮料罐立在浅色木质办公桌上，背景是虚化的办公室环境，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>饮料广告摄影，冷调环境中的暖色产品光，轻微胶片颗粒，</span></span>
<span class="line"><span>微距镜头，浅景深 f/2.0，平视机位，</span></span>
<span class="line"><span>强侧逆光从右后方打来，罐身边缘有明亮的轮廓光，水珠被逆光点亮，背景压暗，</span></span>
<span class="line"><span>竖版 9:16，高细节，无文字</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、变形、多个产品、杂乱背景</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>作用</th></tr></thead><tbody><tr><td>强侧逆光 + 水珠被逆光点亮</td><td>**这一句是产品图显贵的关键。**逆光让水珠变成一颗颗发亮的点，正面光下水珠是灰的</td></tr><tr><td>背景压暗</td><td>提高对比，把产品从环境里&quot;推&quot;出来</td></tr><tr><td>多个产品（负向）</td><td>不排除的话模型爱画一整排</td></tr></tbody></table><p><strong>常见翻车点</strong> 罐身上的品牌标识必然是错的——AI 不认识你的品牌。**实际项目里，罐身要用实拍图或 3D 渲染图合成替换。**这一步没法省。</p><hr><h3 id="prompt-3-·-镜头-4-图生视频-解决动作可控" tabindex="-1">Prompt 3 · 镜头 4 图生视频（解决动作可控） <a class="header-anchor" href="#prompt-3-·-镜头-4-图生视频-解决动作可控" aria-label="Permalink to &quot;Prompt 3 · 镜头 4 图生视频（解决动作可控）&quot;">​</a></h3><p><strong>适用场景</strong> 首帧已满意，让它动起来。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[输入镜头 4 的首帧图]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一颗水珠沿着罐身缓慢向下滑落，</span></span>
<span class="line"><span>镜头以极慢的速度环绕产品，</span></span>
<span class="line"><span>其余部分保持静止</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：快速运动、镜头切换、多个场景、产品变形、文字</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>作用</th></tr></thead><tbody><tr><td>一颗水珠</td><td>**数量写死。**写&quot;水珠滑落&quot;，模型会让一堆水珠乱动</td></tr><tr><td>极慢的速度</td><td>慢是当前视频模型的舒适区，快就畸变</td></tr><tr><td>其余部分保持静止</td><td>不写的话背景会莫名其妙地飘</td></tr><tr><td>产品变形（负向）</td><td>环绕过程中罐身容易被拉伸</td></tr></tbody></table><p><strong>常见翻车点</strong> 动作描述超过一句话就会失控。「水珠滑落，同时镜头环绕，背景人物走过」——三个动作，必崩。<strong>一个镜头一个动作。</strong></p><hr><h2 id="_4-可复用套路" tabindex="-1">④ 可复用套路 <a class="header-anchor" href="#_4-可复用套路" aria-label="Permalink to &quot;④ 可复用套路&quot;">​</a></h2><ol><li><p>**视频链路一律走图生视频。**先用图像模型把画面调满意，再让它动。多一道工序，换来数量级的可控性提升。这是整个案例最重要的一条。</p></li><li><p>**把情绪变化编码进色彩，写进风格包。**冷→暖、暗→亮，让色彩承担叙事。比靠画面内容讲情绪更省镜头，在 15 秒的片子里尤其划算。</p></li><li><p>**液体、气泡、飘落物这类镜头，排期留双倍时间。**它们的废片率显著高于其他镜头，因为物理直觉是视频模型的弱项。报价时把这部分消耗算进去。</p></li><li><p>**产品罐身/瓶身的品牌标识，一律用实拍或渲染图合成替换。**不要试图让 AI 画对，它做不到。生成阶段就当那是个&quot;无标识的产品&quot;来做。</p></li><li><p><strong>动作数量写死。</strong>&quot;一颗水珠&quot;而不是&quot;水珠&quot;，&quot;一个人&quot;而不是&quot;人们&quot;。模型对数量的默认处理是&quot;多个&quot;。</p></li></ol><h2 id="如果重做一次" tabindex="-1">如果重做一次 <a class="header-anchor" href="#如果重做一次" aria-label="Permalink to &quot;如果重做一次&quot;">​</a></h2><p><strong>镜头 3（转头看向产品）应该删掉。</strong></p><p>15 秒里塞 6 个镜头偏多，导致每个镜头只有 2 秒出头，观众来不及看清产品特写。镜头 3 是纯过渡，没有独立信息量——删掉它，把 2 秒还给镜头 4 和 5，产品的展示会扎实很多。</p><p>**教训：过渡镜头是最先该砍的。**短视频里没有&quot;承上启下&quot;的余裕，每个镜头都必须自带信息。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>静态图的批量做法 → <a href="/cases/case-02-ecommerce-visual">案例 02</a></li><li>食品类的食欲感与首尾帧控制 → <a href="/cases/case-03-fries-social">案例 03</a></li><li>分镜方法 → <a href="/method/storyboard">分镜设计</a></li></ul>`,63)])])}const b=a(e,[["render",r]]);export{u as __pageData,b as default};
